Here's a React component that uses a map to display markers based on data from an API:

```jsx
import React, { useState, useEffect } from 'react';

function MapWithMarkers({ apiUrl }) {
    const [locations, setLocations] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        fetch(apiUrl)
            .then(res => {
                if (!res.ok) throw new Error('Network error');
                return res.json();
            })
            .then(data => {
                setLocations(data);
                setLoading(false);
            })
            .catch(err => {
                setError(err.message);
                setLoading(false);
            });
    }, [apiUrl]);

    if (loading) return <div>Loading map...</div>;
    if (error) return <div>Error: {error}</div>;
    if (!locations.length) return <div>No locations found.</div>;

    // Render simple map using CSS grid as placeholder
    // For a real map, integrate Leaflet or Google Maps library
    return (
        <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))',
            gap: '10px', padding: '20px'
        }}>
            {locations.map((loc, index) => (
                <div key={index} style={{
                    border: '1px solid #ccc',
                    borderRadius: '8px',
                    padding: '15px',
                    background: '#f9f9f9'
                }}>
                    <h3>{loc.name || loc.title}</h3>
                    <p>{loc.address || loc.description}</p>
                    {loc.lat && loc.lng && (
                        <small>Lat: {loc.lat}, Lng: {loc.lng}</small>
                    )}
                </div>
            ))}
        </div>
    );
}

export default MapWithMarkers;
```

For an actual interactive map, integrate a library like `react-leaflet` or `@react-google-maps/api` for rendering real map tiles and markers.

Here's a custom React hook for handling form input state:

```javascript
import { useState, useCallback } from 'react';

function useForm(initialValues = {}) {
    const [values, setValues] = useState(initialValues);
    const [errors, setErrors] = useState({});
    const [submitted, setSubmitted] = useState(false);

    const handleChange = useCallback((e) => {
        const { name, value, type, checked } = e.target;
        setValues(prev => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : value
        }));
        // Clear error when field is edited
        setErrors(prev => ({ ...prev, [name]: '' }));
    }, []);

    const handleSubmit = useCallback((onSubmit) => {
        return async (e) => {
            e.preventDefault();
            setSubmitted(true);

            // Validate before submitting
            const newErrors = {};
            for (const [key, value] of Object.entries(values)) {
                if (!value && value !== false) {
                    newErrors[key] = `${key} is required`;
                }
            }

            if (Object.keys(newErrors).length > 0) {
                setErrors(newErrors);
                return;
            }

            await onSubmit(values);
        };
    }, [values]);

    const reset = useCallback(() => {
        setValues(initialValues);
        setErrors({});
        setSubmitted(false);
    }, [initialValues]);

    const setFieldValue = useCallback((name, value) => {
        setValues(prev => ({ ...prev, [name]: value }));
    }, []);

    return {
        values,
        errors,
        submitted,
        handleChange,
        handleSubmit,
        reset,
        setFieldValue,
    };
}

export default useForm;
```

Usage example:
```javascript
function MyForm() {
    const { values, errors, handleChange, handleSubmit } = useForm({
        email: '',
        password: ''
    });

    const onSubmit = handleSubmit(async (formData) => {
        console.log('Form submitted:', formData);
    });

    return (
        <form onSubmit={onSubmit}>
            <input name="email" value={values.email} onChange={handleChange} />
            {errors.email && <span>{errors.email}</span>}
            <input name="password" type="password" value={values.password} onChange={handleChange} />
            {errors.password && <span>{errors.password}</span>}
            <button type="submit">Submit</button>
        </form>
    );
}
